local LA_SV_TailChase = Inherit(CppObjectBase)
function LA_SV_TailChase:Ctor()
self:GenerateBehavior()
self:AddRootComposite("LaxSequencer", self:InstanceLaxSequencer())
self:AddTask("LaxSequencer", "ManeuverLevel", self:InstanceManeuverLevel(1.0, 1.0, "TargetActor", ELiveAIManeuverSpeedType.SpdConstant, 1000.0, 0.1, false))
self:AddComposite("LaxSequencer", "LaxSelector", self:InstanceLaxSelector())
self:AddDecorator("LaxSelector", "IsKDSP1", self:InstanceDecoratorIsKDSP1(true, false))
self:AddComposite("IsKDSP1", "KDS1", self:InstanceLaxSequencer())
self:AddTask("KDS1", "KDS1_Pursuer", self:InstancePursuerTarget(5.0, "TargetActor", 2.0, true, 2500.0, 60.0, false, 120.0, 3.0, 12.0, false, 60.0, 3000.0, false, false, false, FVector.New(-400.0, 0.0, 5.0)))
self:AddTask("KDS1", "KDS1_Straight", self:InstanceManeuverFlyStraight("TargetActor", ELiveAIManeuverSpeedType.SpdConstant, 1000.0, 5.0, false))
self:AddTask("KDS1", "KDS1_MoveAway", self:InstanceSetMoveAwayFromTarget("SelfActor"))
self:AddComposite("LaxSelector", "Skill", self:InstanceRandomSelect())
-- Super (AI level 5 only: Survival's Demon, Phantom and Reaper tiers; 2026-10-23, "a proper fix for the cannon fodder"):
-- the stock LastTGT ace move (a hard 600 km/h turn onto the target, then 10 s 200 m behind it, twice) made longer and
-- closer, with no head-on break and no break-away after it: the tree ends and starts again on the target.
self:AddProbability("Skill", "SuperWeight", self:InstanceWeightProbabilityAILevel(0.0, 0.0, 0.0, 0.0, 1000.0))
self:AddComposite("SuperWeight", "Super", self:InstanceLaxSequencer())
self:AddTask("Super", "SuperTurn", self:InstanceManeuverTurnAdvanced(3.0, 3.0, "TargetActor", ELiveAIManeuverSpeedType.SpdConstant, 600.0, 4.0, false, 500.0))
self:AddTask("Super", "Super1", self:InstancePursuerTarget(15.0, "TargetActor", 100.0, false, 1500.0, 20.0, false, 120.0, 3.0, 10.0, false, 60.0, 3000.0, true, false, true, FVector.New(-150.0, 0.0, 0.0)))
self:AddTask("Super", "SuperTurn2", self:InstanceManeuverTurnAdvanced(3.0, 3.0, "TargetActor", ELiveAIManeuverSpeedType.SpdConstant, 600.0, 4.0, false, 500.0))
self:AddTask("Super", "Super2", self:InstancePursuerTarget(15.0, "TargetActor", 100.0, false, 1500.0, 20.0, false, 120.0, 3.0, 10.0, false, 60.0, 3000.0, true, false, true, FVector.New(-150.0, 0.0, 0.0)))
self:AddProbability("Skill", "TailWeight", self:InstanceWeightProbabilityPilotRank(0.0, 10.0, 30.0, 70.0, 100.0))
self:AddComposite("TailWeight", "Tail", self:InstanceLaxSequencer())
self:AddTask("Tail", "Tail1", self:InstancePursuerTarget(10.0, "TargetActor", 10.0, false, 1500.0, 20.0, false, 120.0, 3.0, 10.0, true, 45.0, 2400.0, true, false, true, FVector.New(-250.0, 0.0, 5.0)))
self:AddTask("Tail", "Reacquire", self:InstanceManeuverTurnAdvanced(3.0, 3.0, "TargetActor", ELiveAIManeuverSpeedType.SpdConstant, 1500.0, 2.0, false, 500.0))
self:AddTask("Tail", "Tail2", self:InstancePursuerTarget(10.0, "TargetActor", 10.0, false, 1500.0, 20.0, false, 120.0, 3.0, 10.0, true, 45.0, 2400.0, true, false, true, FVector.New(-250.0, 0.0, 5.0)))
self:AddTask("Tail", "Tail_MoveAway", self:InstanceSetMoveAwayFromTarget("SelfActor"))
self:AddProbability("Skill", "TightWeight", self:InstanceWeightProbabilityAILevel(0.0, 0.0, 60.0, 100.0, 150.0))
self:AddComposite("TightWeight", "Tight", self:InstanceLaxSequencer())
self:AddTask("Tight", "Tight1", self:InstancePursuerTarget(12.0, "TargetActor", 10.0, false, 1200.0, 20.0, false, 120.0, 3.0, 10.0, true, 45.0, 2400.0, true, false, true, FVector.New(-150.0, 0.0, 5.0)))
self:AddTask("Tight", "TightReacquire", self:InstanceManeuverTurnAdvanced(3.0, 3.0, "TargetActor", ELiveAIManeuverSpeedType.SpdConstant, 1700.0, 1.2, false, 500.0))
self:AddTask("Tight", "Tight2", self:InstancePursuerTarget(12.0, "TargetActor", 10.0, false, 1200.0, 20.0, false, 120.0, 3.0, 10.0, true, 45.0, 2400.0, true, false, true, FVector.New(-150.0, 0.0, 5.0)))
self:AddTask("Tight", "Tight_MoveAway", self:InstanceSetMoveAwayFromTarget("SelfActor"))
self:AddProbability("Skill", "StockWeight", self:InstanceWeightProbabilityPilotRank(100.0, 90.0, 70.0, 30.0, 0.0))
self:AddComposite("StockWeight", "Stock", self:InstanceLaxSequencer())
self:AddComposite("Stock", "Selector", self:InstanceSelector())
self:AddDecorator("Selector", "BlackboardFloat", self:InstanceDecoratorBlackboardFloat("PursuerDistance", 2000.0, EArithmeticKeyOperation.GreaterOrEqual, true))
self:AddTask("BlackboardFloat", "PursuerTarget", self:InstancePursuerTarget(15.0, "TargetActor", 3.0, false, 2000.0, 20.0, false, 120.0, 3.0, 4.0, false, 60.0, 3000.0, true, true, false, FVector.New(-400.0, 0.0, 5.0)))
self:AddTask("Selector", "SetMoveAwayFromTarget", self:InstanceSetMoveAwayFromTarget("SelfActor"))
self:AddTask("Stock", "Stock_MoveAway", self:InstanceSetMoveAwayFromTarget("SelfActor"))
self:EndGenerateBehavior()
end
return LA_SV_TailChase
